// Scan sounds (owner, 2026-11-06): every scan in the ERP beeps, so staff know
// it read without looking at the screen — a different tune per module, and
// per result in Inventaire. Generated by the browser (Web Audio): no sound
// files to load, works offline. Client-only.

export type ScanSound =
  | 'pos' | 'phones' | 'accessories' | 'movements'
  | 'inv_found' | 'inv_duplicate' | 'inv_unknown' | 'inv_outside' | 'inv_ignored'
  | 'error'

type Note = { f: number; ms: number; wave?: OscillatorType; gap?: number; vol?: number }

const TUNES: Record<ScanSound, Note[]> = {
  // Point de vente: two quick rising notes
  pos:           [{ f: 1046, ms: 70 }, { f: 1568, ms: 110 }],
  // Téléphones (list, form): one clear beep
  phones:        [{ f: 1175, ms: 120 }],
  // Accessoires: two equal short beeps
  accessories:   [{ f: 988, ms: 60 }, { f: 988, ms: 60 }],
  // Transferts de stock: three quick beeps
  movements:     [{ f: 880, ms: 50 }, { f: 880, ms: 50 }, { f: 880, ms: 50 }],
  // Inventaire — found: one bright high beep
  inv_found:     [{ f: 1568, ms: 140 }],
  // Inventaire — already scanned: two low beeps
  inv_duplicate: [{ f: 523, ms: 90 }, { f: 523, ms: 90, gap: 70 }],
  // Inventaire — not registered: a long low buzz
  inv_unknown:   [{ f: 196, ms: 450, wave: 'square', vol: 0.12 }],
  // Inventaire — out of scope (sold, in repair…): two falling notes
  inv_outside:   [{ f: 784, ms: 110 }, { f: 392, ms: 180 }],
  // Inventaire — a barcode that isn't an IMEI (box EAN…): a soft tick
  inv_ignored:   [{ f: 300, ms: 45, vol: 0.12 }],
  // something went wrong (network…)
  error:         [{ f: 150, ms: 300, wave: 'sawtooth', vol: 0.12 }],
}

let ctx: AudioContext | null = null

export function playScanSound(kind: ScanSound) {
  if (typeof window === 'undefined') return
  try {
    const Ctx = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!Ctx) return
    ctx ??= new Ctx()
    if (ctx.state === 'suspended') void ctx.resume()
    let t = ctx.currentTime + 0.01
    for (const n of TUNES[kind]) {
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = n.wave ?? 'sine'
      osc.frequency.value = n.f
      const vol = n.vol ?? 0.25
      // short fade in / out: no click
      gain.gain.setValueAtTime(0, t)
      gain.gain.linearRampToValueAtTime(vol, t + 0.008)
      gain.gain.setValueAtTime(vol, t + n.ms / 1000 - 0.015)
      gain.gain.linearRampToValueAtTime(0, t + n.ms / 1000)
      osc.connect(gain).connect(ctx.destination)
      osc.start(t)
      osc.stop(t + n.ms / 1000 + 0.02)
      t += n.ms / 1000 + (n.gap ?? 40) / 1000
    }
    navigator.vibrate?.(kind === 'inv_unknown' || kind === 'error' ? [80, 60, 80] : 40)
  } catch { /* sound is a comfort: never block a scan */ }
}

/**
 * Could be a phone's IMEI as saved in the ERP: 14 to 18 digits (an IMEI is 15;
 * a few were saved with a digit too many or too few — they must still be
 * scannable). A box EAN (12–13 digits), letters or a serial number: no.
 */
export function looksLikeImei(code: string): boolean {
  return /^\d{14,18}$/.test(code.trim())
}

/** A real IMEI: 15 digits whose last one is the Luhn check digit. */
export function isImei(code: string): boolean {
  if (!/^\d{15}$/.test(code)) return false
  let sum = 0
  for (let i = 0; i < 15; i++) {
    let d = Number(code[14 - i])
    if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9 }
    sum += d
  }
  return sum % 10 === 0
}
